From 0dffe25fc26c2b4613002f2885134b9399b5c36d Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:18:14 +0100
Subject: [PATCH] systemd runners: don't pass on our INVOCATION_ID and
 JOURNAL_STREAM

Apps launched as a systemd service or scope got the launcher's own
INVOCATION_ID and JOURNAL_STREAM, so they looked like they belonged to
plasmashell's unit. Drop them, so a service gets the ones of its own unit.

BUG: 487147
---
 src/gui/systemd/scopedprocessrunner.cpp  | 8 ++++++++
 src/gui/systemd/systemdprocessrunner.cpp | 2 ++
 2 files changed, 10 insertions(+)

diff --git a/src/gui/systemd/scopedprocessrunner.cpp b/src/gui/systemd/scopedprocessrunner.cpp
index 4b3a2c476..acc6a4449 100644
--- a/src/gui/systemd/scopedprocessrunner.cpp
+++ b/src/gui/systemd/scopedprocessrunner.cpp
@@ -15,6 +15,14 @@ ScopedProcessRunner::ScopedProcessRunner()

 void ScopedProcessRunner::startProcess()
 {
+    QProcessEnvironment environment = m_process->processEnvironment();
+    if (environment.inheritsFromParent()) {
+        environment = QProcessEnvironment::systemEnvironment();
+    }
+    environment.remove(QStringLiteral("INVOCATION_ID"));
+    environment.remove(QStringLiteral("JOURNAL_STREAM"));
+    m_process->setProcessEnvironment(environment);
+
     std::function oldModifier = m_process->childProcessModifier();
     int efd = eventfd(0, EFD_CLOEXEC);
     m_process->setChildProcessModifier([efd, oldModifier]() {
diff --git a/src/gui/systemd/systemdprocessrunner.cpp b/src/gui/systemd/systemdprocessrunner.cpp
index f4aa4ff06..bb6ba694e 100644
--- a/src/gui/systemd/systemdprocessrunner.cpp
+++ b/src/gui/systemd/systemdprocessrunner.cpp
@@ -93,6 +93,8 @@ bool SystemdProcessRunner::waitForStarted(int timeout)
 static QStringList prepareEnvironment(const QProcessEnvironment &environment)
 {
     QProcessEnvironment allowedEnvironment = environment.inheritsFromParent() ? QProcessEnvironment::systemEnvironment() : environment;
+    allowedEnvironment.remove(QStringLiteral("INVOCATION_ID"));
+    allowedEnvironment.remove(QStringLiteral("JOURNAL_STREAM"));
     auto allowedBySystemd = [](const QChar c) {
         return c.isDigit() || c.isLetter() || c == u'_';
     };
